#!/usr/bin/env bash
# Downloads the site photos from the Facebook page into images/.
# The Facebook links are temporary (valid until about 23.11.2026).
# If they have expired, save the photos manually from the Facebook page with the same file names.
set -u
cd "$(dirname "$0")/.."
mkdir -p images
fail=0
get() {
  if curl -fsSL --max-time 60 -o "images/$1.jpg" "$2"; then echo "ok   $1.jpg"; else echo "FAIL $1.jpg"; fail=1; fi
}
